import { useRef, useCallback, useEffect, useState } from 'react';
import { Audio, type AVPlaybackStatus } from 'expo-av';

export type AudioPlayerState = {
  isPlaying: boolean;
  positionMs: number;
  durationMs: number;
};

type UseAudioPlayerReturn = {
  // Narration
  narrationState: AudioPlayerState;
  loadNarration: (uri: string) => Promise<void>;
  playNarration: () => Promise<void>;
  pauseNarration: () => Promise<void>;
  seekNarration: (positionMs: number) => Promise<void>;
  setNarrationVolume: (volume: number) => Promise<void>;
  // Soundscape
  soundscapeState: AudioPlayerState;
  loadSoundscape: (uri: string) => Promise<void>;
  playSoundscape: () => Promise<void>;
  pauseSoundscape: () => Promise<void>;
  setSoundscapeVolume: (volume: number) => Promise<void>;
  // Crossfade
  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
  fadeOutSoundscape: (duration?: number) => Promise<void>;
  // Cleanup
  cleanup: () => Promise<void>;
};

export function useAudioPlayer(): UseAudioPlayerReturn {
  const narrationRef = useRef<Audio.Sound | null>(null);
  const soundscapeRef = useRef<Audio.Sound | null>(null);
  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  // Configure audio mode for background playback
  useEffect(() => {
    Audio.setAudioModeAsync({
      playsInSilentModeIOS: true,
      staysActiveInBackground: true,
      shouldDuckAndroid: true,
    });
  }, []);

  const handleNarrationStatus = useCallback((status: AVPlaybackStatus) => {
    if (!status.isLoaded) return;
    setNarrationState({
      isPlaying: status.isPlaying,
      positionMs: status.positionMillis,
      durationMs: status.durationMillis ?? 0,
    });
  }, []);

  const handleSoundscapeStatus = useCallback((status: AVPlaybackStatus) => {
    if (!status.isLoaded) return;
    setSoundscapeState({
      isPlaying: status.isPlaying,
      positionMs: status.positionMillis,
      durationMs: status.durationMillis ?? 0,
    });
  }, []);

  // Narration controls
  const loadNarration = useCallback(async (uri: string) => {
    if (narrationRef.current) {
      await narrationRef.current.unloadAsync();
    }
    const { sound } = await Audio.Sound.createAsync(
      { uri },
      { shouldPlay: false, progressUpdateIntervalMillis: 50 },
      handleNarrationStatus
    );
    narrationRef.current = sound;
  }, [handleNarrationStatus]);

  const playNarration = useCallback(async () => {
    await narrationRef.current?.playAsync();
  }, []);

  const pauseNarration = useCallback(async () => {
    await narrationRef.current?.pauseAsync();
  }, []);

  const seekNarration = useCallback(async (positionMs: number) => {
    await narrationRef.current?.setPositionAsync(positionMs);
  }, []);

  const setNarrationVolume = useCallback(async (volume: number) => {
    await narrationRef.current?.setVolumeAsync(volume);
  }, []);

  // Soundscape controls
  const loadSoundscape = useCallback(async (uri: string) => {
    if (soundscapeRef.current) {
      await soundscapeRef.current.unloadAsync();
    }
    const { sound } = await Audio.Sound.createAsync(
      { uri },
      { shouldPlay: false, isLooping: true, volume: 0.6 },
      handleSoundscapeStatus
    );
    soundscapeRef.current = sound;
  }, [handleSoundscapeStatus]);

  const playSoundscape = useCallback(async () => {
    await soundscapeRef.current?.playAsync();
  }, []);

  const pauseSoundscape = useCallback(async () => {
    await soundscapeRef.current?.pauseAsync();
  }, []);

  const setSoundscapeVolume = useCallback(async (volume: number) => {
    await soundscapeRef.current?.setVolumeAsync(volume);
  }, []);

  // Fade out over duration
  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
    const sound = soundscapeRef.current;
    if (!sound) return;

    const status = await sound.getStatusAsync();
    if (!status.isLoaded) return;

    const startVolume = status.volume;
    const steps = 20;
    const stepDuration = duration / steps;
    const volumeStep = startVolume / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(async () => {
        currentStep++;
        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
        await sound.setVolumeAsync(newVolume);

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
          await sound.pauseAsync();
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Crossfade: fade out current, load new, fade in
  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
    const oldSound = soundscapeRef.current;

    // Load new sound at volume 0
    const { sound: newSound } = await Audio.Sound.createAsync(
      { uri: newUri },
      { shouldPlay: true, isLooping: true, volume: 0 },
      handleSoundscapeStatus
    );

    // Fade out old, fade in new simultaneously
    const steps = 15;
    const stepDuration = duration / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(async () => {
        currentStep++;
        const progress = currentStep / steps;

        // Fade in new
        await newSound.setVolumeAsync(0.6 * progress);

        // Fade out old
        if (oldSound) {
          try {
            await oldSound.setVolumeAsync(0.6 * (1 - progress));
          } catch {
            // Old sound may already be unloaded
          }
        }

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

          // Cleanup old
          if (oldSound) {
            try {
              await oldSound.unloadAsync();
            } catch {
              // Ignore
            }
          }

          soundscapeRef.current = newSound;
          resolve();
        }
      }, stepDuration);
    });
  }, [handleSoundscapeStatus]);

  // Cleanup all audio
  const cleanup = useCallback(async () => {
    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    if (narrationRef.current) {
      try {
        await narrationRef.current.unloadAsync();
      } catch { /* ignore */ }
      narrationRef.current = null;
    }

    if (soundscapeRef.current) {
      try {
        await soundscapeRef.current.unloadAsync();
      } catch { /* ignore */ }
      soundscapeRef.current = null;
    }

    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  return {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    seekNarration,
    setNarrationVolume,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup,
  };
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { useAudioPlayer, type AudioPlayerState } from './useAudioPlayer';
import { useLocalPreferences } from './useLocalPreferences';
import type { PageData } from '@/types';

type UseReaderAudioProps = {
  pageData: PageData | undefined;
  bookId: string;
};

type UseReaderAudioReturn = {
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationState: AudioPlayerState;
  soundscapeState: AudioPlayerState;
  toggleNarration: () => Promise<void>;
  toggleSoundscape: () => Promise<void>;
  loadNarration: (url: string) => Promise<void>;
  loadSoundscape: (url: string) => Promise<void>;
  cleanup: () => void;
};

export function useReaderAudio({ pageData }: UseReaderAudioProps): UseReaderAudioReturn {
  const {
    narrationState,
    loadNarration: loadNarrationAudio,
    playNarration,
    pauseNarration,
    soundscapeState,
    loadSoundscape: loadSoundscapeAudio,
    playSoundscape,
    pauseSoundscape,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup: cleanupAudio,
  } = useAudioPlayer();

  const { preferences } = useLocalPreferences();

  const [isNarrationActive, setIsNarrationActive] = useState(false);
  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);

  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const introFadedPages = useRef(new Set<number>());
  const prevSoundscapeUrl = useRef<string | null>(null);

  const currentPage = pageData?.pageNumber ?? 1;

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
  const soundscapeUrl = soundscapeAssignment?.audioUrl;

  // Load narration audio when page changes
  useEffect(() => {
    if (narrationUrl) {
      loadNarrationAudio(narrationUrl).then(() => {
        if (isNarrationActive) {
          playNarration();
        }
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [narrationUrl]);

  // Handle soundscape changes with crossfade
  useEffect(() => {
    if (!soundscapeUrl) return;

    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
      crossfadeSoundscape(soundscapeUrl);
    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
      loadSoundscapeAudio(soundscapeUrl).then(() => {
        if (isSoundscapeActive) playSoundscape();
      });
    }
    prevSoundscapeUrl.current = soundscapeUrl;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [soundscapeUrl]);

  // Intro-only mode: fade out after 10 seconds
  useEffect(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }

    if (
      preferences.soundscapeMode === 'intro-only' &&
      isSoundscapeActive &&
      soundscapeUrl &&
      !introFadedPages.current.has(currentPage)
    ) {
      introFadeTimerRef.current = setTimeout(() => {
        introFadedPages.current.add(currentPage);
        fadeOutSoundscape(3000).then(() => {
          setIsSoundscapeActive(false);
        });
      }, 10000);
    }

    return () => {
      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
    };
  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanupAudio();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleNarration = useCallback(async () => {
    if (isNarrationActive) {
      await pauseNarration();
      setIsNarrationActive(false);
    } else if (narrationUrl) {
      await playNarration();
      setIsNarrationActive(true);
    }
  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);

  const toggleSoundscape = useCallback(async () => {
    if (isSoundscapeActive) {
      await pauseSoundscape();
      setIsSoundscapeActive(false);
    } else if (soundscapeUrl) {
      await playSoundscape();
      setIsSoundscapeActive(true);
    }
  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);

  const loadNarration = useCallback(
    async (url: string) => {
      await loadNarrationAudio(url);
    },
    [loadNarrationAudio]
  );

  const loadSoundscape = useCallback(
    async (url: string) => {
      await loadSoundscapeAudio(url);
    },
    [loadSoundscapeAudio]
  );

  const cleanup = useCallback(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }
    cleanupAudio();
  }, [cleanupAudio]);

  return {
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,
    toggleNarration,
    toggleSoundscape,
    loadNarration,
    loadSoundscape,
    cleanup,
  };
}

import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { BlurView } from 'expo-blur';
import Animated, {
  useAnimatedStyle,
  withTiming,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { fonts } from '@/lib/theme';

type Props = {
  hasNarration: boolean;
  hasSoundscape: boolean;
  isNarrationPlaying: boolean;
  isSoundscapePlaying: boolean;
  onToggleNarration: () => void;
  onToggleSoundscape: () => void;
  isVisible?: boolean;
};

export const AudioControls = React.memo(function AudioControls({
  hasNarration,
  hasSoundscape,
  isNarrationPlaying,
  isSoundscapePlaying,
  onToggleNarration,
  onToggleSoundscape,
  isVisible = true,
}: Props) {
  const insets = useSafeAreaInsets();
  const hasAudio = hasNarration || hasSoundscape;
  const shouldShow = hasAudio && isVisible;

  const containerStyle = useAnimatedStyle(() => ({
    opacity: withTiming(shouldShow ? 1 : 0, { duration: 250 }),
    transform: [{ translateY: withTiming(shouldShow ? 0 : 20, { duration: 250 }) }],
  }));

  return (
    <Animated.View
      style={[
        styles.container,
        { bottom: Math.max(24, insets.bottom + 8) },
        containerStyle,
      ]}
      pointerEvents={shouldShow ? 'auto' : 'none'}
    >
      <BlurView
        intensity={50}
        tint="dark"
        style={styles.backgroundBlur}
      >
        <View style={styles.pillRow}>
          {hasNarration && (
            <TouchableOpacity onPress={onToggleNarration} activeOpacity={0.7} hitSlop={20}>
              <BlurView
                intensity={30}
                tint="dark"
                style={[
                  styles.pill,
                  isNarrationPlaying && styles.pillActiveNarration,
                ]}
              >
                <Text style={styles.pillEmoji}>
                  {isNarrationPlaying ? '\u{23F8}' : '\u{1F3A4}'}
                </Text>
                <Text
                  style={[
                    styles.pillText,
                    {
                      color: isNarrationPlaying ? '#ffffff' : 'rgba(255,255,255,0.85)',
                      fontFamily: fonts.sans,
                    },
                  ]}
                >
                  {isNarrationPlaying ? 'Pause' : 'Read'}
                </Text>
              </BlurView>
            </TouchableOpacity>
          )}

          {hasSoundscape && (
            <TouchableOpacity onPress={onToggleSoundscape} activeOpacity={0.7} hitSlop={20}>
              <BlurView
                intensity={30}
                tint="dark"
                style={[
                  styles.pill,
                  isSoundscapePlaying && styles.pillActiveSoundscape,
                ]}
              >
                <Text style={styles.pillEmoji}>
                  {isSoundscapePlaying ? '\u{1F50A}' : '\u{1F3B5}'}
                </Text>
                <Text
                  style={[
                    styles.pillText,
                    {
                      color: isSoundscapePlaying ? '#ffffff' : 'rgba(255,255,255,0.85)',
                      fontFamily: fonts.sans,
                    },
                  ]}
                >
                  {isSoundscapePlaying ? 'Mute' : 'Sound'}
                </Text>
              </BlurView>
            </TouchableOpacity>
          )}
        </View>
      </BlurView>
    </Animated.View>
  );
});

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    left: 0,
    right: 0,
    zIndex: 40,
    alignItems: 'center',
    paddingHorizontal: 16,
  },
  backgroundBlur: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 12,
    paddingVertical: 10,
    borderRadius: 32,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.1)',
  },
  pillRow: {
    flexDirection: 'row',
    gap: 10,
  },
  pill: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    paddingVertical: 14,
    paddingHorizontal: 20,
    borderRadius: 24,
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.12)',
    overflow: 'hidden',
    minHeight: 52,
    minWidth: 100,
    justifyContent: 'center',
  },
  pillActiveNarration: {
    backgroundColor: 'rgba(249, 115, 22, 0.9)',
    borderColor: 'rgba(251, 146, 60, 0.7)',
  },
  pillActiveSoundscape: {
    backgroundColor: 'rgba(20, 184, 166, 0.9)',
    borderColor: 'rgba(45, 212, 191, 0.7)',
  },
  pillEmoji: {
    fontSize: 18,
  },
  pillText: {
    fontSize: 14,
    fontWeight: '600',
    letterSpacing: 0.3,
  },
});

import React, { createContext, useContext, useState, useCallback, useMemo, useEffect, useRef, ReactNode } from 'react';
import { useRouter } from 'expo-router';
import * as Haptics from 'expo-haptics';
import { useSharedValue } from 'react-native-reanimated';
import { useReaderData } from '@/hooks/useBookData';
import { useReadingProgress, useAutoSaveProgress } from '@/hooks/useReadingProgress';
import { useAudioPlayer } from '@/hooks/useAudioPlayer';
import { useLocalPreferences } from '@/hooks/useLocalPreferences';
import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
import type { PageData, ReaderResponse } from '@/types';

type AudioPlayerState = {
  isPlaying: boolean;
  positionMs: number;
  durationMs: number;
};

interface ReaderContextValue {
  // Page state
  activeIndex: number;
  totalPages: number;
  currentPage: number;
  progressPercent: number;
  pages: PageData[];

  // Audio state
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationState: AudioPlayerState;
  soundscapeState: AudioPlayerState;

  // UI visibility state
  isUIVisible: boolean;

  // Actions
  goToPage: (index: number) => void;
  toggleNarration: () => void;
  toggleSoundscape: () => void;
  handleClose: () => void;
  toggleUI: () => void;
  showUI: () => void;
  hideUI: () => void;

  // Data
  readerData: ReaderResponse | undefined;
  isLoading: boolean;
  error: Error | null;

  // Utility
  visiblePageIndices: number[];

  // Internal (for gesture handling)
  translateY: ReturnType<typeof useSharedValue<number>>;
  activeIndexShared: ReturnType<typeof useSharedValue<number>>;
  getPageAnimatedStyle: ReturnType<typeof usePageAnimatedStyle>;
  setActiveIndexInternal: (index: number) => void;

  // Audio URLs for current page
  narrationUrl: string | null;
  soundscapeUrl: string | null;
}

const ReaderContext = createContext<ReaderContextValue | null>(null);

interface ReaderProviderProps {
  bookId: string;
  children: ReactNode;
}

export function ReaderProvider({ bookId, children }: ReaderProviderProps) {
  const router = useRouter();

  // Data
  const { data: readerData, isLoading, error } = useReaderData(bookId);
  const { data: savedProgress } = useReadingProgress(bookId);

  // State
  const [activeIndex, setActiveIndex] = useState(0);
  const [isUIVisible, setIsUIVisible] = useState(true);
  const progressRestoredRef = useRef(false);

  // Shared values for gestures
  const translateY = useSharedValue(0);
  const activeIndexShared = useSharedValue(0);
  const getPageAnimatedStyle = usePageAnimatedStyle(translateY, activeIndexShared);

  // Audio
  const {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup,
  } = useAudioPlayer();

  const [isNarrationActive, setIsNarrationActive] = useState(false);
  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);

  // Preferences
  const { preferences } = useLocalPreferences();
  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const introFadedPages = useRef(new Set<number>());

  // Derived
  const pages = useMemo(
    () => [...(readerData?.pages ?? [])].sort((a, b) => a.pageNumber - b.pageNumber),
    [readerData?.pages]
  );
  const totalPages = pages.length;
  const currentPage = pages[activeIndex]?.pageNumber ?? 1;
  const pageData: PageData | undefined = pages[activeIndex];
  const progressPercent = totalPages > 0 ? ((activeIndex + 1) / totalPages) * 100 : 0;

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl || null;
  const soundscapeUrl = soundscapeAssignment?.audioUrl || null;

  // Visible pages (virtualization window of ±1)
  const visiblePageIndices = useMemo(() => {
    const indices: number[] = [];
    for (let i = Math.max(0, activeIndex - 1); i <= Math.min(totalPages - 1, activeIndex + 1); i++) {
      indices.push(i);
    }
    return indices;
  }, [activeIndex, totalPages]);

  // Auto-save progress
  useAutoSaveProgress({
    bookId,
    currentPage,
    totalPages,
    enabled: !isLoading && totalPages > 0,
  });

  // Restore reading progress
  useEffect(() => {
    if (progressRestoredRef.current || isLoading || !readerData) return;

    if (savedProgress?.currentPage && savedProgress.currentPage > 1 && savedProgress.currentPage <= totalPages) {
      const idx = pages.findIndex((p) => p.pageNumber === savedProgress.currentPage);
      if (idx > 0) {
        setActiveIndex(idx);
        activeIndexShared.value = idx;
      }
    }
    progressRestoredRef.current = true;
  }, [savedProgress, isLoading, readerData, totalPages, pages, activeIndexShared]);

  // Load narration audio when page changes
  useEffect(() => {
    if (narrationUrl) {
      loadNarration(narrationUrl).then(() => {
        if (isNarrationActive) {
          playNarration();
        }
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [narrationUrl]);

  // Handle soundscape changes with crossfade
  const prevSoundscapeUrl = useRef<string | null>(null);
  useEffect(() => {
    if (!soundscapeUrl) return;

    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
      crossfadeSoundscape(soundscapeUrl);
    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
      loadSoundscape(soundscapeUrl).then(() => {
        if (isSoundscapeActive) playSoundscape();
      });
    }
    prevSoundscapeUrl.current = soundscapeUrl;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [soundscapeUrl]);

  // Intro-only mode: fade out after 10 seconds
  useEffect(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }

    if (
      preferences.soundscapeMode === 'intro-only' &&
      isSoundscapeActive &&
      soundscapeUrl &&
      !introFadedPages.current.has(currentPage)
    ) {
      introFadeTimerRef.current = setTimeout(() => {
        introFadedPages.current.add(currentPage);
        fadeOutSoundscape(3000).then(() => {
          setIsSoundscapeActive(false);
        });
      }, 10000);
    }

    return () => {
      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
    };
  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Actions
  const goToPage = useCallback((index: number) => {
    if (index >= 0 && index < totalPages) {
      setActiveIndex(index);
      activeIndexShared.value = index;
      translateY.value = 0;
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
  }, [totalPages, activeIndexShared, translateY]);

  const toggleNarration = useCallback(async () => {
    if (isNarrationActive) {
      await pauseNarration();
      setIsNarrationActive(false);
    } else if (narrationUrl) {
      await playNarration();
      setIsNarrationActive(true);
    }
  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);

  const toggleSoundscape = useCallback(async () => {
    if (isSoundscapeActive) {
      await pauseSoundscape();
      setIsSoundscapeActive(false);
    } else if (soundscapeUrl) {
      await playSoundscape();
      setIsSoundscapeActive(true);
    }
  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);

  const handleClose = useCallback(() => {
    cleanup();
    router.back();
  }, [router, cleanup]);

  // Internal setter for gesture handling
  const setActiveIndexInternal = useCallback((index: number) => {
    setActiveIndex(index);
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  }, []);

  // UI visibility actions
  const toggleUI = useCallback(() => {
    setIsUIVisible((prev) => {
      const newValue = !prev;
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      return newValue;
    });
  }, []);

  const showUI = useCallback(() => {
    setIsUIVisible(true);
  }, []);

  const hideUI = useCallback(() => {
    setIsUIVisible(false);
  }, []);

  const value: ReaderContextValue = {
    // Page state
    activeIndex,
    totalPages,
    currentPage,
    progressPercent,
    pages,

    // Audio state
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,

    // UI visibility state
    isUIVisible,

    // Actions
    goToPage,
    toggleNarration,
    toggleSoundscape,
    handleClose,
    toggleUI,
    showUI,
    hideUI,

    // Data
    readerData,
    isLoading,
    error,

    // Utility
    visiblePageIndices,

    // Internal
    translateY,
    activeIndexShared,
    getPageAnimatedStyle,
    setActiveIndexInternal,

    // Audio URLs
    narrationUrl,
    soundscapeUrl,
  };

  return <ReaderContext.Provider value={value}>{children}</ReaderContext.Provider>;
}

export function useReader() {
  const context = useContext(ReaderContext);
  if (!context) {
    throw new Error('useReader must be used within a ReaderProvider');
  }
  return context;
}

import React, { useCallback, useMemo } from 'react';
import { View, Dimensions } from 'react-native';
import { useSharedValue, withSpring, runOnJS } from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import { useReader } from '@/contexts/ReaderContext';
import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
import { PageLayer } from './PageLayer';
import type { PageData } from '@/types';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');
const SWIPE_THRESHOLD = SCREEN_HEIGHT * 0.18;
const VELOCITY_THRESHOLD = 500;

const SPRING_CONFIG = {
  damping: 22,
  stiffness: 200,
  mass: 1,
};

export function ReaderContainer() {
  const { pages, activeIndex, goToPage } = useReader();

  const translateY = useSharedValue(0);
  const activeIndexShared = useSharedValue(activeIndex);

  const getPageAnimatedStyle = usePageAnimatedStyle(translateY, activeIndexShared);

  const totalPages = pages.length;

  const updateIndex = useCallback(
    (newIndex: number) => {
      goToPage(newIndex);
    },
    [goToPage]
  );

  const panGesture = Gesture.Pan()
    .activeOffsetY([-15, 15])
    .onUpdate((e) => {
      const idx = activeIndexShared.value;
      if (idx === 0 && e.translationY > 0) {
        translateY.value = e.translationY * 0.3;
      } else if (idx === totalPages - 1 && e.translationY < 0) {
        translateY.value = e.translationY * 0.3;
      } else {
        translateY.value = e.translationY;
      }
    })
    .onEnd((e) => {
      const idx = activeIndexShared.value;
      const swipedUp = e.translationY < -SWIPE_THRESHOLD || e.velocityY < -VELOCITY_THRESHOLD;
      const swipedDown = e.translationY > SWIPE_THRESHOLD || e.velocityY > VELOCITY_THRESHOLD;

      if (swipedUp && idx < totalPages - 1) {
        activeIndexShared.value = idx + 1;
        translateY.value = withSpring(0, SPRING_CONFIG);
        runOnJS(updateIndex)(idx + 1);
      } else if (swipedDown && idx > 0) {
        activeIndexShared.value = idx - 1;
        translateY.value = withSpring(0, SPRING_CONFIG);
        runOnJS(updateIndex)(idx - 1);
      } else {
        translateY.value = withSpring(0, SPRING_CONFIG);
      }
    });

  const visiblePages = useMemo(() => {
    return pages.filter((_: PageData, i: number) => Math.abs(i - activeIndex) <= 1);
  }, [pages, activeIndex]);

  React.useEffect(() => {
    activeIndexShared.value = activeIndex;
  }, [activeIndex, activeIndexShared]);

  return (
    <GestureDetector gesture={panGesture}>
      <View style={{ flex: 1 }}>
        {visiblePages.map((page: PageData) => {
          const pageIndex = pages.indexOf(page);
          return (
            <PageLayer
              key={page.id}
              page={page}
              pageIndex={pageIndex}
              activeIndex={activeIndex}
              narrationTimestamps={page.narrationTimestamps ?? null}
              currentPositionMs={0}
              isNarrationPlaying={false}
              usePageAnimatedStyle={getPageAnimatedStyle}
            />
          );
        })}
      </View>
    </GestureDetector>
  );
}

import { useEffect, useState, useRef, useCallback, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Dimensions,
  TouchableOpacity,
} from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import * as Haptics from 'expo-haptics';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  runOnJS,
} from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import { useReaderData } from '@/hooks/useBookData';
import { useReadingProgress, useAutoSaveProgress } from '@/hooks/useReadingProgress';
import { useReaderAudio } from '@/hooks/useReaderAudio';
import { useThemeColors, fonts } from '@/lib/theme';
import { ReaderTopBar } from '@/components/ReaderTopBar';
import { AudioControls } from '@/components/AudioControls';
import { PageRenderer } from '@/components/PageRenderer';
import { SwipePageIndicator } from '@/components/SwipePageIndicator';
import { PageLayer } from '@/components/reader/PageLayer';
import { EdgeTapZones } from '@/components/reader/EdgeTapZones';
import { usePageAnimatedStyle } from '@/hooks/useReaderAnimations';
import { ReaderSkeleton } from '@/components/Skeleton';
import { GestureTutorial, hasSeenGestureTutorial, markGestureTutorialSeen } from '@/components/reader/GestureTutorial';
import type { PageData } from '@/types';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
const SWIPE_THRESHOLD = SCREEN_HEIGHT * 0.18;
const VELOCITY_THRESHOLD = 500;

const SPRING_CONFIG = {
  damping: 22,
  stiffness: 200,
  mass: 1,
};

const UI_ANIMATION_DURATION = 250;

export default function ReaderScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const colors = useThemeColors();
  const bookId = id ?? '';

  // Data
  const { data: readerData, isLoading, error, refetch } = useReaderData(bookId);
  const { data: savedProgress } = useReadingProgress(bookId);

  // State
  const [activeIndex, setActiveIndex] = useState(0);
  const [showSettings, setShowSettings] = useState(false);
  const [isUIVisible, setIsUIVisible] = useState(true);
  const [showTutorial, setShowTutorial] = useState(false);
  const progressRestoredRef = useRef(false);
  const tutorialCheckedRef = useRef(false);

  // Derived
  const pages = useMemo(
    () => [...(readerData?.pages ?? [])].sort((a, b) => a.pageNumber - b.pageNumber),
    [readerData?.pages]
  );
  const totalPages = pages.length;
  const currentPage = pages[activeIndex]?.pageNumber ?? 1;
  const pageData: PageData | undefined = pages[activeIndex];
  const progressPercent = totalPages > 0 ? ((activeIndex + 1) / totalPages) * 100 : 0;

  // Audio
  const {
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,
    toggleNarration,
    toggleSoundscape,
    cleanup,
  } = useReaderAudio({ pageData, bookId });

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
  const soundscapeUrl = soundscapeAssignment?.audioUrl;

  // ═══════════════════════════════════════════════════════════════
  // REANIMATED GESTURE PAGER
  // ═══════════════════════════════════════════════════════════════

  const translateY = useSharedValue(0);
  const activeIndexShared = useSharedValue(0);
  const getPageAnimatedStyle = usePageAnimatedStyle(translateY, activeIndexShared);

  const updateActiveIndex = useCallback(
    (newIndex: number) => {
      setActiveIndex(newIndex);
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    },
    []
  );

  const panGesture = Gesture.Pan()
    .activeOffsetY([-15, 15])
    .onUpdate((e) => {
      // Clamp: don't allow overscroll past first/last page
      const idx = activeIndexShared.value;
      if (idx === 0 && e.translationY > 0) {
        // Rubber band at top
        translateY.value = e.translationY * 0.3;
      } else if (idx === totalPages - 1 && e.translationY < 0) {
        // Rubber band at bottom
        translateY.value = e.translationY * 0.3;
      } else {
        translateY.value = e.translationY;
      }
    })
    .onEnd((e) => {
      const idx = activeIndexShared.value;
      const swipedUp = e.translationY < -SWIPE_THRESHOLD || e.velocityY < -VELOCITY_THRESHOLD;
      const swipedDown = e.translationY > SWIPE_THRESHOLD || e.velocityY > VELOCITY_THRESHOLD;

      if (swipedUp && idx < totalPages - 1) {
        // Go to next page
        activeIndexShared.value = idx + 1;
        translateY.value = withSpring(0, SPRING_CONFIG);
        runOnJS(updateActiveIndex)(idx + 1);
      } else if (swipedDown && idx > 0) {
        // Go to previous page
        activeIndexShared.value = idx - 1;
        translateY.value = withSpring(0, SPRING_CONFIG);
        runOnJS(updateActiveIndex)(idx - 1);
      } else {
        // Snap back (dead zone)
        translateY.value = withSpring(0, SPRING_CONFIG);
      }
    });

  // Tap to toggle UI visibility
  const tapGesture = Gesture.Tap()
    .maxDuration(250)
    .onEnd(() => {
      runOnJS(toggleUI)();
    });

  // Combine gestures - Race allows pan to win when swiping, tap to win on tap
  const composedGesture = Gesture.Race(panGesture, tapGesture);

  const toggleUI = useCallback(() => {
    setIsUIVisible((prev) => {
      const newValue = !prev;
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      return newValue;
    });
  }, []);

  // ═══════════════════════════════════════════════════════════════
  // PROGRESS
  // ═══════════════════════════════════════════════════════════════

  useAutoSaveProgress({
    bookId,
    currentPage,
    totalPages,
    enabled: !isLoading && totalPages > 0,
  });

  // Restore reading progress
  useEffect(() => {
    if (progressRestoredRef.current || isLoading || !readerData) return;

    if (savedProgress?.currentPage && savedProgress.currentPage > 1 && savedProgress.currentPage <= totalPages) {
      const idx = pages.findIndex((p) => p.pageNumber === savedProgress.currentPage);
      if (idx > 0) {
        setActiveIndex(idx);
        activeIndexShared.value = idx;
      }
    }
    progressRestoredRef.current = true;
  }, [savedProgress, isLoading, readerData, totalPages, pages, activeIndexShared]);

  // ═══════════════════════════════════════════════════════════════
  // GESTURE TUTORIAL (FTUE)
  // ═══════════════════════════════════════════════════════════════

  useEffect(() => {
    if (tutorialCheckedRef.current || isLoading) return;

    const checkTutorial = async () => {
      const hasSeen = await hasSeenGestureTutorial();
      if (!hasSeen) {
        setShowTutorial(true);
      }
      tutorialCheckedRef.current = true;
    };

    checkTutorial();
  }, [isLoading]);

  const handleTutorialComplete = useCallback(() => {
    setShowTutorial(false);
    markGestureTutorialSeen();
  }, []);

  // ═══════════════════════════════════════════════════════════════
  // CLEANUP
  // ═══════════════════════════════════════════════════════════════

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleClose = useCallback(() => {
    cleanup();
    router.back();
  }, [router, cleanup]);

  // ═══════════════════════════════════════════════════════════════
  // EDGE TAP NAVIGATION
  // ═══════════════════════════════════════════════════════════════

  const goToPreviousPage = useCallback(() => {
    if (activeIndex > 0) {
      const newIndex = activeIndex - 1;
      setActiveIndex(newIndex);
      activeIndexShared.value = newIndex;
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
  }, [activeIndex, activeIndexShared]);

  const goToNextPage = useCallback(() => {
    if (activeIndex < totalPages - 1) {
      const newIndex = activeIndex + 1;
      setActiveIndex(newIndex);
      activeIndexShared.value = newIndex;
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
  }, [activeIndex, totalPages, activeIndexShared]);

  // Animated styles for UI visibility
  const topBarAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
  }));

  const audioControlsAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 1 : 0, { duration: UI_ANIMATION_DURATION }),
  }));

  const tapHintAnimatedStyle = useAnimatedStyle(() => ({
    opacity: withTiming(isUIVisible ? 0 : 0.5, { duration: UI_ANIMATION_DURATION }),
  }));

  // ═══════════════════════════════════════════════════════════════
  // VISIBLE PAGES (virtualization window of ±1)
  // Optimized: O(1) slice instead of O(n) filter + indexOf
  // ═══════════════════════════════════════════════════════════════

  const visiblePages = useMemo(() => {
    const start = Math.max(0, activeIndex - 1);
    const end = Math.min(pages.length - 1, activeIndex + 1);
    const result: { page: typeof pages[0]; index: number }[] = [];
    for (let i = start; i <= end; i++) {
      result.push({ page: pages[i], index: i });
    }
    return result;
  }, [pages, activeIndex]);

  // ═══════════════════════════════════════════════════════════════
  // RENDER
  // ═══════════════════════════════════════════════════════════════

  if (isLoading) {
    return <ReaderSkeleton />;
  }

  if (error || !readerData) {
    return (
      <View style={[styles.centered, { backgroundColor: colors.readerBg }]}>
        <Text style={[styles.errorTitle, { color: colors.error, fontFamily: fonts.sans }]}>
          Oops!
        </Text>
        <Text style={[styles.errorText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
          {error?.message || 'Book not found'}
        </Text>
        <View style={styles.errorButtonsContainer}>
          <TouchableOpacity
            style={[styles.primaryButton, { backgroundColor: colors.readerProgressBarFill }]}
            onPress={() => refetch()}
            activeOpacity={0.8}
          >
            <Text style={[styles.primaryButtonText, { color: colors.readerBg, fontFamily: fonts.sans }]}>
              Try Again
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.secondaryButton, { borderColor: colors.readerTextSecondary }]}
            onPress={() => router.back()}
            activeOpacity={0.8}
          >
            <Text style={[styles.secondaryButtonText, { color: colors.readerTextSecondary, fontFamily: fonts.sans }]}>
              Go Back
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.container, { backgroundColor: colors.readerBg }]}>
      <GestureDetector gesture={composedGesture}>
        <View style={styles.pagerContainer}>
          {visiblePages.map(({ page, index }) => (
            <PageLayer
              key={page.id}
              page={page}
              pageIndex={index}
              activeIndex={activeIndex}
              narrationTimestamps={page.narrationTimestamps ?? null}
              currentPositionMs={narrationState.positionMs}
              isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
              usePageAnimatedStyle={getPageAnimatedStyle}
            />
          ))}
        </View>
      </GestureDetector>

      {/* Floating UI */}
      <Animated.View
        style={[styles.topBarContainer, topBarAnimatedStyle]}
        pointerEvents={isUIVisible ? 'auto' : 'none'}
      >
        <ReaderTopBar
          progressPercent={progressPercent}
          currentPage={currentPage}
          totalPages={totalPages}
          onClose={handleClose}
          onSettings={() => setShowSettings(true)}
        />
      </Animated.View>

      <Animated.View
        style={[styles.audioControlsContainer, audioControlsAnimatedStyle]}
        pointerEvents={isUIVisible ? 'auto' : 'none'}
      >
        <AudioControls
          hasNarration={!!narrationUrl}
          hasSoundscape={!!soundscapeUrl}
          isNarrationPlaying={isNarrationActive && narrationState.isPlaying}
          isSoundscapePlaying={isSoundscapeActive && soundscapeState.isPlaying}
          onToggleNarration={toggleNarration}
          onToggleSoundscape={toggleSoundscape}
        />
      </Animated.View>

      <SwipePageIndicator visible={isUIVisible && activeIndex === 0 && totalPages > 1} />

      {/* Edge Tap Zones - only visible when UI is hidden */}
      {!isUIVisible && (
        <EdgeTapZones
          onPrevious={goToPreviousPage}
          onNext={goToNextPage}
          isVisible={!isUIVisible}
        />
      )}

      {/* Tap hint when UI is hidden */}
      <Animated.View style={[styles.tapHintContainer, tapHintAnimatedStyle]} pointerEvents="none">
        <Text style={[styles.tapHintText, { color: colors.readerTextSecondary }]}>
          Tap to show controls
        </Text>
      </Animated.View>

      <GestureTutorial
        visible={showTutorial}
        onComplete={handleTutorialComplete}
      />
    </View>
  );
}

