        translateY.value = withSpring(0, SPRING_CONFIG);
        runOnJS(updateActiveIndex)(idx - 1);
      } else {
        // Snap back (dead zone)
        translateY.value = withSpring(0, SPRING_CONFIG);
      }
    });

  // Tap to toggle UI visibility
  const tapGesture = Gesture.Tap()
    .maxDuration(250)
    .onEnd(() => {
